package cn.local.gaokao;
import android.text.*;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.content.Context;
import android.widget.*;
import org.json.*;
import java.util.*;
/** Search and examples share the exact dictionary destination; no learning writes. */
final class DictionaryPanel {
 final MainActivity a;final Runnable back;String query="";LinearLayout results;android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());Runnable pending;
 DictionaryPanel(MainActivity a,Runnable back){this.a=a;this.back=back;}
 void show(){boolean fromHome=a.page.equals("home");a.screen("dictionary");a.childHeader("词汇搜索",()->{hideKeyboard();back.run();});a.dock.setVisibility(View.GONE);EditText search=new EditText(a);search.setSingleLine();search.setHint("输入要查询的词语、句子或释义");search.setTextSize(16);search.setContentDescription("词汇搜索框");search.setBackground(a.bg(0x88ffffff,14));search.setPadding(a.dp(12),a.dp(8),a.dp(12),a.dp(8));a.root.addView(search,new LinearLayout.LayoutParams(-1,a.dp(50)));results=new LinearLayout(a);results.setOrientation(1);a.root.addView(results);search.setText(query);update();search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int after){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int before,int count){query=s.toString();if(pending!=null)handler.removeCallbacks(pending);pending=()->{if(a.page.equals("dictionary"))update();};handler.postDelayed(pending,160);}});search.requestFocus();search.postDelayed(()->{if(a.page.equals("dictionary"))((InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(search,InputMethodManager.SHOW_IMPLICIT);},fromHome?MainActivity.CONTENT_MOTION_MS+40:250);}
 void update(){results.removeAllViews();try{JSONArray matches=WordLexicon.examples(a,query);if(matches.length()==0&&!query.trim().isEmpty()){TextView empty=new TextView(a);empty.setText("暂无匹配例句");results.addView(empty);}else append(matches,0);}catch(Exception e){a.error("无法读取词典");}}
 void append(JSONArray matches,int from)throws Exception{int end=Math.min(from+40,matches.length());for(int n=from;n<end;n++){JSONObject c=matches.getJSONObject(n);example(c.getString("dictionary_word"),c);}if(end<matches.length()){Button more=a.action("更多例句（"+end+"/"+matches.length()+"）",()->{});more.setOnClickListener(v->{results.removeView(more);try{append(matches,end);}catch(Exception e){a.error("无法继续读取例句");}});results.addView(more);}}

 void hideKeyboard(){if(a.getCurrentFocus()!=null)((InputMethodManager)a.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(a.getCurrentFocus().getWindowToken(),0);}
 void detail(String term){hideKeyboard();a.screen("dictionaryDetail");a.childHeader(term,query.isEmpty()?back:this::show);a.dock.setVisibility(View.GONE);try{JSONArray hits=WordLexicon.matches(a,term);ArrayList<JSONObject> exact=new ArrayList<>();for(int i=0;i<hits.length();i++){JSONObject card=hits.getJSONObject(i);if(term.equals(card.optString("word")))exact.add(card);}LinearLayout top=new LinearLayout(a);top.setGravity(Gravity.CENTER_VERTICAL);TextView heading=new TextView(a);heading.setText(term);heading.setTextSize(30);heading.setTextColor(WordLexicon.ORANGE);top.addView(heading,new LinearLayout.LayoutParams(0,-2,1));a.root.addView(top);a.label("例句",16);JSONArray contexts=new JSONArray();for(JSONObject card:exact){JSONArray cs=card.getJSONArray("contexts");for(int j=0;j<cs.length();j++)contexts.put(cs.getJSONObject(j));}contexts=WordLexicon.unique(contexts);if(contexts.length()==0){a.note("未收录该词的独立词条");return;}for(int n=0;n<contexts.length();n++)example(term,contexts.getJSONObject(n));}catch(Exception e){a.error("无法读取词汇例句");}}
 void exampleDetail(String term,JSONObject c){hideKeyboard();a.screen("dictionaryExample");a.childHeader("例句释义",back);a.dock.setVisibility(View.GONE);example(term,c);}
 void example(String term,JSONObject c){
  LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(a.dp(16),a.dp(14),a.dp(12),a.dp(18));box.setBackground(a.bg(0xbfffffff,14));box.setTag("example:"+ExampleCollections.key(c));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=a.dp(12);(a.page.equals("dictionary")?results:a.root).addView(box,lp);
  LinearLayout line=new LinearLayout(a);line.setGravity(Gravity.TOP);TextView sentence=new TextView(a);sentence.setTextSize(21);sentence.setTextColor(a.INK);sentence.setLineSpacing(a.dp(7),1);WordLexicon.clickable(a,sentence,WordLexicon.sentence(c.optString("sentence")),term,WordLexicon.displayTarget(c,term));line.addView(sentence,new LinearLayout.LayoutParams(0,-2,1));
  ExampleCollections favorites=new ExampleCollections(a);Button star=a.action(favorites.saved(c)?"★":"☆",()->{});star.setTextSize(24);star.setTextColor(favorites.saved(c)?WordLexicon.ORANGE:a.MUTED);star.setMinWidth(0);star.setPadding(0,0,0,0);star.setTag("example-star:"+ExampleCollections.key(c));star.setContentDescription("收藏这条例句");star.setOnClickListener(v->favorites.choose(term,c,()->{boolean on=favorites.saved(c);star.setText(on?"★":"☆");star.setTextColor(on?WordLexicon.ORANGE:a.MUTED);}));line.addView(star,new LinearLayout.LayoutParams(a.dp(44),a.dp(44)));box.addView(line);
  String source=WordLexicon.section(a,c);TextView origin=new TextView(a);origin.setText("— "+(source.isEmpty()?WordLexicon.title(c.optString("title")):source));origin.setTextColor(a.MUTED);origin.setTextSize(12);origin.setPadding(0,a.dp(10),0,a.dp(14));box.addView(origin);TextView meaning=new TextView(a);meaning.setText(term+"："+c.optString("meaning"));meaning.setTextSize(19);meaning.setTextColor(a.INK);box.addView(meaning);String translation=WordLexicon.translation(a,c);if(!translation.isEmpty()){TextView t=new TextView(a);t.setText(translation);t.setTextColor(a.MUTED);t.setTextSize(14);t.setLineSpacing(a.dp(6),1);t.setPadding(0,a.dp(9),0,0);box.addView(t);}
 }

 void quote(String quote){query="";try{JSONArray hits=WordLexicon.matches(a,quote);for(int i=0;i<hits.length();i++)if(quote.equals(hits.getJSONObject(i).optString("word"))){detail(quote);return;}String best="";JSONArray all=a.textbookWords().getJSONArray("cards");for(int i=0;i<all.length();i++){String w=all.getJSONObject(i).optString("word");if(quote.contains(w)&&w.length()>best.length())best=w;}if(!best.isEmpty())detail(best);else show();}catch(Exception e){show();}}
}
